cat > src/clock.c <<'EOF'
#define _POSIX_C_SOURCE 200809L
#define _DEFAULT_SOURCE
#include <ncurses.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <ctype.h>
#include <limits.h>
#include "messages.h"

typedef struct {
    int seconds, screensaver, box, centered, bold, twelve;
    int utc, rebound, noquit, nodate, blink, color;
    long delay, nsdelay;
    const char *format;
    FILE *terminal;
    SCREEN *screen;
    WINDOW *digits, *date;
    int x, y, width, date_width;
    int dx, dy;
    struct tm now;
    char date_text[1024];
} Clock;

static Clock clock_state = {
    .color = 2, .delay = 1, .format = "%Y-%m-%d",
    .width = 35, .dx = 1, .dy = 1
};
static volatile sig_atomic_t active = 1;

static void stopped(int sig)
{
    (void)sig;
    active = 0;
    endwin();
    exit(0);
}

static void read_time(void)
{
    Clock *c = &clock_state;
    time_t t = time(NULL);
    if (c->utc) gmtime_r(&t, &c->now);
    else localtime_r(&t, &c->now);
    c->date_text[0] = '\0';
    strftime(c->date_text, sizeof(c->date_text) - 6, c->format, &c->now);
    if (c->twelve) strcat(c->date_text, c->now.tm_hour < 12 ? " [AM]" : " [PM]");
}

static int date_x(void)
{
    Clock *c = &clock_state;
    return c->x + c->width / 2 - c->date_width / 2;
}

static void draw_border(WINDOW *w)
{
    if (!w) return;
    if (clock_state.box) box(w, 0, 0);
    else wborder(w, ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ');
}

static const char glyphs[10][5][4] = {
    {"111", "101", "101", "101", "111"},
    {"001", "001", "001", "001", "001"},
    {"111", "001", "111", "100", "111"},
    {"111", "001", "111", "001", "111"},
    {"101", "101", "111", "001", "001"},
    {"111", "100", "111", "001", "111"},
    {"111", "100", "111", "101", "111"},
    {"111", "001", "001", "001", "001"},
    {"111", "101", "111", "101", "111"},
    {"111", "101", "111", "001", "111"}
};

static void paint_digit(int n, int x)
{
    Clock *c = &clock_state;
    if (!c->digits) return;
    for (int row = 0; row < 5; row++) {
        for (int col = 0; col < 3; col++) {
            wattrset(c->digits, (c->bold ? A_BLINK : A_NORMAL) |
                     (glyphs[n][row][col] == '1' ? COLOR_PAIR(1) : COLOR_PAIR(0)));
            mvwaddstr(c->digits, row + 1, x + col * 2, "  ");
        }
    }
    wrefresh(c->digits);
}

static void paint_colon(int x)
{
    Clock *c = &clock_state;
    if (!c->digits) return;
    int pair = c->blink && !(c->now.tm_sec & 1) ? 2 : 1;
    wattrset(c->digits, COLOR_PAIR(pair) | (c->bold ? A_BLINK : A_NORMAL));
    mvwaddstr(c->digits, 2, x, "  ");
    mvwaddstr(c->digits, 4, x, "  ");
    wattrset(c->digits, c->bold ? A_BLINK : A_NORMAL);
}

static void paint(void)
{
    Clock *c = &clock_state;
    int h = c->now.tm_hour;
    if (c->twelve) h = h % 12 ? h % 12 : 12;
    paint_digit(h / 10, 1);
    paint_digit(h % 10, 8);
    paint_colon(16);
    paint_digit(c->now.tm_min / 10, 20);
    paint_digit(c->now.tm_min % 10, 27);
    if (c->seconds) {
        paint_colon(35);
        paint_digit(c->now.tm_sec / 10, 39);
        paint_digit(c->now.tm_sec % 10, 46);
    }
    if (!c->nodate && c->date) {
        wattrset(c->date, COLOR_PAIR(2) | (c->bold ? A_BOLD : A_NORMAL));
        mvwaddstr(c->date, 1, 1, c->date_text);
        wattrset(c->date, A_NORMAL);
        wrefresh(c->date);
    }
}

static void clear_window(WINDOW *w)
{
    if (w) {
        werase(w);
        wrefresh(w);
    }
}

static void move_clock(int x, int y)
{
    Clock *c = &clock_state;
    clear_window(c->digits);
    if (!c->nodate) clear_window(c->date);
    if (c->digits && mvwin(c->digits, y, x) == OK) {
        c->x = x;
        c->y = y;
    }
    draw_border(c->digits);
    wrefresh(c->digits);
    if (!c->nodate && c->date) {
        mvwin(c->date, c->y + 6, date_x());
        draw_border(c->date);
        wrefresh(c->date);
    }
}

static void center_clock(void)
{
    Clock *c = &clock_state;
    int x = COLS / 2 - c->width / 2;
    int y = LINES / 2 - 3;
    if (x < 0 || y < 0) { x = 0; y = 0; }
    move_clock(x, y);
}

static void reshape(void)
{
    Clock *c = &clock_state;
    clear_window(c->digits);
    if (!c->nodate) clear_window(c->date);
    c->width = c->seconds ? 54 : 35;
    c->date_width = (int)strlen(c->date_text) + 2;
    if (c->digits) wresize(c->digits, 7, c->width);
    if (c->date) wresize(c->date, 3, c->date_width);
    move_clock(c->x, c->y);
    if (c->centered) center_clock();
}

static void set_color(int color)
{
    clock_state.color = color;
    init_pair(1, -1, color);
    init_pair(2, color, -1);
}

static void bounce(void)
{
    Clock *c = &clock_state;
    if (c->x + c->width >= COLS) c->dx = -1;
    else if (c->x <= 0) c->dx = 1;
    if (c->y + 9 >= LINES) c->dy = -1;
    else if (c->y <= 0) c->dy = 1;
    move_clock(c->x + c->dx, c->y + c->dy);
}

static int process_key(int key)
{
    Clock *c = &clock_state;
    if (key >= 0 && key < 256) key = tolower(key);
    if (key >= '0' && key <= '7') { set_color(key - '0'); return 1; }
    switch (key) {
    case 'q': if (!c->noquit) active = 0; break;
    case 'h': if (!c->centered && c->x > 0) { move_clock(c->x-1, c->y); return 1; } break;
    case 'l': if (!c->centered && c->x + c->width < COLS) { move_clock(c->x+1, c->y); return 1; } break;
    case 'k': if (!c->centered && c->y > 0) { move_clock(c->x, c->y-1); return 1; } break;
    case 'j': if (!c->centered && c->y + 9 < LINES) { move_clock(c->x, c->y+1); return 1; } break;
    case 'c': c->centered = !c->centered; c->rebound = 0; if (c->centered) { center_clock(); return 1; } break;
    case 'r': c->rebound = 1; c->centered = 0; return 1;
    case 's': c->seconds = !c->seconds; reshape(); return 1;
    case 't': c->twelve = !c->twelve; read_time(); reshape(); return 1;
    case 'b': c->bold = !c->bold; return 1;
    case 'x':
        c->box = !c->box;
        draw_border(c->date); wrefresh(c->date);
        draw_border(c->digits); wrefresh(c->digits);
        return 1;
    case KEY_RESIZE:
        clear(); refresh();
        if (c->centered) center_clock();
        else move_clock(c->x, c->y);
        return 1;
    default: break;
    }
    return 0;
}

static void open_terminal(const char *path)
{
    struct stat st;
    if (stat(path, &st) < 0) {
        fprintf(stderr, "tty-clock: error: couldn't stat '%s': %s.\n", path, strerror(errno));
        exit(1);
    }
    if (!S_ISCHR(st.st_mode)) {
        fprintf(stderr, "tty-clock: error: '%s' doesn't appear to be a character device.\n", path);
        exit(1);
    }
    FILE *f = fopen(path, "r+");
    if (!f) {
        fprintf(stderr, "tty-clock: error: '%s' couldn't be opened: %s.\n", path, strerror(errno));
        exit(1);
    }
    if (clock_state.terminal) fclose(clock_state.terminal);
    clock_state.terminal = f;
}

static void options(int argc, char **argv)
{
    Clock *c = &clock_state;
    int opt;
    while ((opt = getopt(argc, argv, "iuvsScbtrahDBxnC:f:d:a:T:")) != -1) {
        switch (opt) {
        case 'i': puts("TTY-Clock 2 © by Martin Duquesnoy (xorg62@gmail.com), Grey (grey@greytheory.net)"); exit(0);
        case 'v': puts("TTY-Clock 2 © devel version"); exit(0);
        case 's': c->seconds = 1; break;
        case 'S': c->screensaver = 1; break;
        case 'x': c->box = 1; break;
        case 'c': c->centered = 1; break;
        case 'b': c->bold = 1; break;
        case 't': c->twelve = 1; break;
        case 'u': c->utc = 1; break;
        case 'r': c->rebound = 1; break;
        case 'n': c->noquit = 1; break;
        case 'D': c->nodate = 1; break;
        case 'B': c->blink = 1; break;
        case 'C': { int n = atoi(optarg); if (n >= 0 && n <= 7) c->color = n; break; }
        case 'f': c->format = optarg; break;
        case 'd': c->delay = atol(optarg); break;
        case 'a': c->nsdelay = atol(optarg); break;
        case 'T': open_terminal(optarg); break;
        default: fputs(usage_text, stdout); exit(0);
        }
    }
    c->width = c->seconds ? 54 : 35;
}

static void initialize(void)
{
    Clock *c = &clock_state;
    if (c->terminal) {
        c->screen = newterm(NULL, c->terminal, c->terminal);
        if (!c->screen) {
            fprintf(stderr, "executable: ttyclock.c:53: init: Assertion `ttyclock.ttyscr != NULL' failed.\n");
            abort();
        }
        set_term(c->screen);
    } else initscr();
    keypad(stdscr, TRUE);
    start_color();
    use_default_colors();
    curs_set(0);
    noecho();
    cbreak();
    set_color(c->color);
    clear();
    refresh();
